--
-- Name: v_initiative_plan; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_initiative_plan AS
 WITH pv AS (
         SELECT p.initiative_id,
            p.name,
            p.direction,
            p.start_month,
            p.cost_rub,
            p.months_to_profit,
            p.months_to_payback,
            ( SELECT sum(((p.cost_rub / (p.months_to_profit)::numeric) / power(1.01, ((p.start_month + t.t))::numeric))) AS sum
                   FROM generate_series(0, (p.months_to_profit - 1)) t(t)) AS spend_pv,
            ( SELECT sum(((1)::numeric / power(1.01, ((p.start_month + t.t))::numeric))) AS sum
                   FROM generate_series(p.months_to_profit, p.months_to_payback) t(t)) AS unit_pv
           FROM public.initiative_passport p
        )
 SELECT initiative_id,
    name,
    direction,
    start_month,
    cost_rub,
    months_to_profit,
    months_to_payback,
    floor((cost_rub / (months_to_profit)::numeric)) AS monthly_cost_rub,
    ceil((spend_pv / unit_pv)) AS monthly_profit_rub
   FROM pv;


--
-- Name: VIEW v_initiative_plan; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_initiative_plan IS 'Паспорт инициативы, развёрнутый в план: сколько тратим в месяц и сколько зарабатываем после выхода на прибыльность';


--
-- Name: v_initiative_cashflow; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_initiative_cashflow AS
 SELECT pl.initiative_id,
    pl.name,
    pl.direction,
    m.month_index,
        CASE
            WHEN (m.month_index < pl.start_month) THEN (0)::numeric
            WHEN (m.month_index < (pl.start_month + pl.months_to_profit)) THEN (- pl.monthly_cost_rub)
            ELSE pl.monthly_profit_rub
        END AS cash_flow_rub,
    round((
        CASE
            WHEN (m.month_index < pl.start_month) THEN (0)::numeric
            WHEN (m.month_index < (pl.start_month + pl.months_to_profit)) THEN (- pl.monthly_cost_rub)
            ELSE pl.monthly_profit_rub
        END / power(1.01, (m.month_index)::numeric)), 2) AS discounted_rub
   FROM (public.v_initiative_plan pl
     CROSS JOIN generate_series(0, 36) m(month_index));


--
-- Name: v_initiative_fact_vs_plan; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_initiative_fact_vs_plan AS
 SELECT f.initiative_id,
    pl.name,
    pl.direction,
    f.month_index,
    f.actual_cost_rub,
    f.actual_profit_rub,
        CASE
            WHEN (f.month_index < (pl.start_month + pl.months_to_profit)) THEN pl.monthly_cost_rub
            ELSE (0)::numeric
        END AS plan_cost_rub,
        CASE
            WHEN (f.month_index >= (pl.start_month + pl.months_to_profit)) THEN pl.monthly_profit_rub
            ELSE (0)::numeric
        END AS plan_profit_rub
   FROM (public.initiative_fact f
     JOIN public.v_initiative_plan pl USING (initiative_id));


--
-- Name: VIEW v_initiative_fact_vs_plan; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_initiative_fact_vs_plan IS 'План и факт по месяцам: видно, где инициатива отстаёт от паспорта';


--
-- Name: v_initiative_npv; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_initiative_npv AS
 SELECT initiative_id,
    name,
    direction,
    month_index,
    cash_flow_rub,
    discounted_rub,
    sum(discounted_rub) OVER (PARTITION BY initiative_id ORDER BY month_index) AS cum_npv_rub
   FROM public.v_initiative_cashflow;


--
-- Name: VIEW v_initiative_npv; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_initiative_npv IS 'Кривая NPV каждой инициативы по месяцам';


--
-- Name: v_portfolio_npv; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_portfolio_npv AS
 SELECT month_index,
    sum(cash_flow_rub) AS cash_flow_rub,
    sum(discounted_rub) AS discounted_rub,
    sum(sum(discounted_rub)) OVER (ORDER BY month_index) AS cum_npv_rub
   FROM public.v_initiative_cashflow
  GROUP BY month_index;


--
-- Name: VIEW v_portfolio_npv; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_portfolio_npv IS 'Сумма кривых инициатив — кривая всего портфеля';


